await dataSource.transaction(async (em: EntityManager) => {   // one unit of work
  const customer = await em.findOneOrFail(Customer, { where: { id } });
  customer.name = name;                       // dirty in memory only
  await em.save(customer);                    // written through the transaction
  await em.save(Audit, { customerId: id });   // use em, never the global manager
});                                           // commit on return, rollback on throw

