const qr = dataSource.createQueryRunner();
await qr.connect();
await qr.startTransaction();
try {
  await qr.manager.save(customer);          // transactional EntityManager
  await qr.manager.save(Audit, { customerId: id });
  await qr.commitTransaction();
} catch (e) {
  await qr.rollbackTransaction(); throw e;
} finally {
  await qr.release();                       // never leak the connection
}

